// nomiExternKey is the key one host declaration registers under FOR THIS LOAD,
// which is ONE key and not two.
//
// NOTE FOR AN EDITOR: this comment is inside a Go RAW STRING LITERAL (the
// wrapper template), so it must not contain a backtick. A backtick here
// terminates the literal and the file stops parsing several declarations
// later, which reads as an error in unrelated code.
//
// The runtime qualifies a non-entry file's host declarations with its module
// name and the ENTRY's with nothing, so 'ffi.nomi' declares 'ffi.echo_upper'
// when 'main.nomi' is the entry and 'echo_upper' when it is the entry itself.
// Discovery cannot know which file will be loaded — a project has many — so it
// emits both spellings and this function picks the one that applies.
//
// ONE key, chosen, rather than binding both: the program crosses under exactly
// one of them.
//
// entry is "" for a declaration whose key does not depend on the entry: an
// owner-qualified one ('impl Box { host fn … }') keys on the receiver type, and
// a file with no module name already has the entry's shape.
//
// declared is every file that declares the binding under module's key: two
// files with the same base name and no go.mod above them share that key.
//
// Symlinks are resolved because the two paths reach here by different routes —
// one is an argument the user typed, the other came out of a filesystem walk.
// A resolution failure falls back to string equality, which is the same answer
// for every path with no symlink in it.
//
// A built executable passes its image's name for the entry, which is relative
// to the project root (vmhost names image files as go build -trimpath does):
// it is the declaring file when it ends that file's path at a separator.
func nomiExternKey(target, module, entry string, declared ...string) string {
	if entry == "" {
		return module
	}
	rt, terr := stdfilepath.EvalSymlinks(target)
	for _, d := range declared {
		if target == d {
			return entry
		}
		// A prebuilt runner names a declaring file by its module's path and
		// its path in the module, and the target is in the module cache,
		// where the module's directory ends in @ and its version.
		if !stdfilepath.IsAbs(d) && stdfilepath.IsAbs(target) {
			if s := nomiWithoutVersions(stdfilepath.ToSlash(target)); len(s) > len(d) && s[len(s)-len(d)-1:] == "/"+d {
				return entry
			}
			continue
		}
		if !stdfilepath.IsAbs(target) {
			if s := stdfilepath.ToSlash(d); len(s) > len(target) && s[len(s)-len(target)-1:] == "/"+target {
				return entry
			}
			continue
		}
		rd, derr := stdfilepath.EvalSymlinks(d)
		if terr == nil && derr == nil && rt == rd {
			return entry
		}
	}
	return module
}

// nomiWithoutVersions is path with each element's @version removed, so a file
// in the module cache reads as its module's path and its path in the module.
func nomiWithoutVersions(path string) string {
	out := make([]byte, 0, len(path))
	skip := false
	for i := 0; i < len(path); i++ {
		switch c := path[i]; {
		case c == '/':
			skip = false
			out = append(out, c)
		case c == '@':
			skip = true
		case !skip:
			out = append(out, c)
		}
	}
	return string(out)
}
